//! Parity with the macOS app: shared/test-vectors/*.json are generated by the Swift code
//! (`Murmur --dump-test-vectors`); the Rust core must reproduce every expected value.

use murmur_core::cleanup::{basic_clean, needs_llm};
use murmur_core::dictionary::{finalize, DictEntry};
use murmur_core::replay::{Event, Move, ReplayModel};
use murmur_core::vocab;
use serde_json::Value;
use std::collections::HashSet;
use std::path::PathBuf;

fn load(name: &str) -> Vec<Value> {
    let p = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../shared/test-vectors").join(name);
    let s = std::fs::read_to_string(&p).unwrap_or_else(|e| panic!("{}: {e}", p.display()));
    serde_json::from_str(&s).unwrap()
}

fn s(v: &Value, k: &str) -> String {
    v[k].as_str().unwrap_or("").to_string()
}

fn cand_json(c: &Option<vocab::Candidate>) -> Value {
    match c {
        None => Value::Null,
        Some(c) => serde_json::json!({"heard": c.heard, "wanted": c.wanted}),
    }
}

fn event(v: &Value) -> Event {
    match v["type"].as_str().unwrap() {
        "text" => Event::Text(s(v, "text")),
        "backspace" => Event::Backspace,
        "forward_delete" => Event::ForwardDelete,
        "delete_word" => Event::DeleteWord,
        "delete_line" => Event::DeleteLine,
        "select_all" => Event::SelectAll,
        "undo" => Event::Undo,
        "unsupported" => Event::Unsupported,
        "move" => {
            let m = match v["move"].as_str().unwrap() {
                "left" => Move::Left,
                "right" => Move::Right,
                "word_left" => Move::WordLeft,
                "word_right" => Move::WordRight,
                "line_start" => Move::LineStart,
                "line_end" => Move::LineEnd,
                o => panic!("unknown move {o}"),
            };
            Event::Move(m, v["select"].as_bool().unwrap())
        }
        o => panic!("unknown event {o}"),
    }
}

/// Reports every mismatch (instead of stopping at the first) so CI logs show the full picture.
fn finish(name: &str, total: usize, fails: Vec<String>) {
    for f in &fails {
        eprintln!("MISMATCH {name}: {f}");
    }
    assert!(fails.is_empty(), "{name}: {} of {total} vectors failed", fails.len());
}

#[test]
fn cleanup_vectors() {
    let cases = load("cleanup.json");
    let mut fails = vec![];
    for c in &cases {
        let input = s(c, "input");
        let got = basic_clean(&input);
        if got != s(c, "expected") {
            fails.push(format!("clean {input:?}: got {got:?}, want {:?}", s(c, "expected")));
        }
        let nl = needs_llm(&input, true);
        if nl != c["needs_llm"].as_bool().unwrap() {
            fails.push(format!("needs_llm {input:?}: got {nl}"));
        }
    }
    finish("cleanup", cases.len(), fails);
}

#[test]
fn dictionary_vectors() {
    let cases = load("dictionary.json");
    let mut fails = vec![];
    for c in &cases {
        let entries: Vec<DictEntry> = serde_json::from_value(c["entries"].clone()).unwrap();
        let got = finalize(&s(c, "input"), &s(c, "before"), &entries);
        if got != s(c, "expected") {
            fails.push(format!("{:?} + {entries:?} (before {:?}): got {got:?}, want {:?}", s(c, "input"), s(c, "before"), s(c, "expected")));
        }
    }
    finish("dictionary", cases.len(), fails);
}

#[test]
fn learn_vectors() {
    let cases = load("learn.json");
    let mut fails = vec![];
    let none = HashSet::new();
    for c in &cases {
        match c["kind"].as_str().unwrap() {
            "candidate" => {
                let got = cand_json(&vocab::candidate(&s(c, "pasted"), &s(c, "edited"), &[], &none));
                if got != c["expected"] {
                    fails.push(format!("candidate {:?} -> {:?}: got {got}, want {}", s(c, "pasted"), s(c, "edited"), c["expected"]));
                }
            }
            "replay" => {
                let pasted = s(c, "pasted");
                let mut m = ReplayModel::new(&pasted);
                for e in c["events"].as_array().unwrap() {
                    m.apply(event(e));
                }
                let res = m.result();
                let want_res = c["result"].as_str().map(String::from);
                if res != want_res {
                    fails.push(format!("replay {pasted:?}: result {res:?}, want {want_res:?}"));
                }
                let want_frozen = c["frozen"].as_str().map(String::from);
                if m.frozen != want_frozen {
                    fails.push(format!("replay {pasted:?}: frozen {:?}, want {want_frozen:?}", m.frozen));
                }
                let got = cand_json(&res.and_then(|r| vocab::candidate(&pasted, &r, &[], &none)));
                if got != c["expected"] {
                    fails.push(format!("replay-candidate {pasted:?}: got {got}, want {}", c["expected"]));
                }
            }
            o => panic!("unknown kind {o}"),
        }
    }
    finish("learn", cases.len(), fails);
}
